def subtract(a, b):
    # Filter out empty intervals and sort
    a_valid = sorted([interval for interval in a if interval[0] < interval[1]])
    b_valid = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_valid:
        return []

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_valid:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Compute a - b
    result = []
    for a_start, a_end in a_valid:
        current = a_start
        for b_start, b_end in b_merged:
            # No overlap
            if b_end <= current or b_start >= a_end:
                continue
            # b overlaps with [current, a_end)
            if b_start > current:
                result.append([current, b_start])
            current = max(current, b_end)

        if current < a_end:
            result.append([current, a_end])

    # Merge touching intervals in result
    merged = []
    for start, end in result:
        if merged and start == merged[-1][1]:
            merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

